from pathlib import Path
import json,hashlib,datetime,shutil
p=Path(__file__).resolve().parent
for f in p.rglob('__pycache__'):
 if f.is_dir():shutil.rmtree(f)
def load(name):return json.loads((p/name).read_text())
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
scoped={platform:load('scoped-check-'+platform+'.json')for platform in ['ios','android']}
rows=[]
for name in ['probe-ios','probe-android','main-ios-r1','main-android-r1']:
 m=load('evidence/'+name+'/manifest.json');log=load('logs/'+name+'.json')
 rows.append({'run':name,'native_test_count':m['native_test_count'],'screenshot_count':len(m['image_hashes']),'command_wall_seconds':log['wall_seconds'],'manifest_wall_seconds':m['finished_at']-m['started_at'],'command_exit':log['exit_code'],'status':m['status']})
report={'test':'Independent neutral Reading Notes forward test','frozen_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'independence':'This separate agent received only the requirement and Skill/tool schema/examples, then fixed the original typed reference before writing component code or rendering. No past result or business submission inspected. The design is agent-authored; hash identity does not certify human approval or correct interpretation.','original_design_lock_sha256':load('APPROVAL.json')['design_lock_sha256'],'scoped_design_lock_sha256':load('APPROVAL-SCOPED.json')['design_lock_sha256'],'component':'Real reusable ReadingNotes Swift package component and real Android main-source Composable, directly instantiated by thin caller bridges. Twelve long rows, initial/opened/replaced selected states; caller replacement preserves local open state.','native_runs':rows,'schema_amendment':'The root neutral probe identified AX/semantic bounds versus layout allocation ambiguity during this run. Preserved original pre-scope contract, plan, tooling snapshot and results. New lock only adds explicit layout_box measurement and approval metadata. Numeric source bytes, selectors, fixtures, action routes and component sources remain unchanged. Scoped replay uses the original raw native observation; no recollection claimed.','final_scoped_result':{k:{'status':v['status'],'counts':v['counts'],'assertion_denominator':len(v['assertions']),'matrix_cells':len(v['matrix_contract']['cells']),'na_cells':sum(r['disposition']=='not_applicable'for r in v['matrix_contract']['cells']),'unassessed':[r['id']for r in v['assertions']if r['status']=='unassessed'],'failed_assertion_ids':v['failed_assertion_ids']}for k,v in scoped.items()},'visual_result':'All five overlapping initial native frames per platform inspected from heading through the fully visible footer. Readable complete sentences, hierarchy, separated markers/action/status and calm blue/pale surfaces pass visual intent. Also inspected immediate/post-action and replacement top/footer frames. Exact unsupported typography/layout allocation is not inferred from pixels.','negative_tests':{'original_attempt':{'rejected':10,'accepted':1,'defect':'Selector-object extra expected field accepted by compile but did not override the sealed expected value. Full initial accepted output retained.'},'fixed_replay':{'rejected':11,'accepted':0,'source':'rejections-final/results.json'},'categories':['source hash mismatch','inline expected literal','missing rule/state cell','wrong native geometry unit','binding expected override','action route mutation','changed generated expectation','changed tolerance','changed provenance','deleted rule coverage','changed state coverage']},'ui_loop':'Initial viewport capture/review passes per platform. The profile stages an exact existing frame only after validating every current native source hash, original inputs, full image hashes, observation digest and executed test count/exit. Staging explicitly records reuse of this session\'s fresh native run; this is not a second native execution or a full-content numerical pass.','usability':'Usable as an evidence-first native component workflow with pinned hosts. CLI outputs and typed-source provenance are inspectable, and updates/callback intervals are state-bound. Contract drafting/binding is substantial manual work. iOS main capture costs 118s for 12 rows because the observer performs multiple full sweeps as well as target navigation. No natural-language completeness or design-author correctness proof.','limits':['Both collectors expose accessibility/semantic bounds; layout_box width and gap remain U on both platforms (6 cells each).','iOS public AX does not expose font_sp or color_argb for this SwiftUI text (6 additional U cells). Android actual text layout matches 16sp and #FF204B6D in all three selected states.','One 390-width light/LTR default-size scenario only; no dark, RTL, accessibility text size, narrow-width or localization claims.','iOS uses real simulator App/XCUITest. Android uses attached ComposeView/Paparazzi native semantics and OnClick, without Activity/device physical-touch claims.','Thin-host scrolling and caller replacement are covered; no business app navigation, keyboard, safe-area or lifecycle coverage claimed.','No independent raster golden; visual review is fallible agent judgment. Two N/A stimulus classes and target-only state visual limits remain in the matrix.','Tooling changed during this independent run. Exact pre-scope, intermediate and final snapshots are retained. Original negative tests before the selector fix did not capture the pre-fix tool bytes; the acceptance input/output is retained and root independently patched it.'],'failures_and_retries':['Bootstrap caller mistake: pre-created workspace caused FileExistsError; corrected with fresh hosts child directory. Summary retained in early-failure.json; successful setup log retained.','Initial negative suite intentionally failed its all-rejected assertion because a binding extra expected field was accepted. Root fixed the validation; exact fresh CLI retry rejects, then all 11 final probes reject.','Scoped compile first attempted nonexistent copied CLI after a diagnostic tail failed before the tool-copy command; both exit2 logs retained. Copied the final snapshot separately, reran the same compiles, both passed.','No native build/test failure, no product correction iteration, no source/expectation tuning after screenshot feedback.'],'tool_snapshots':{'pre_scope':'tools-used/sha256.json','intermediate_scope':'tools-scoped/sha256.json','final_scope':'tools-final/sha256.json'},'portable_evidence':'All112 native PNG snapshots plus raw observations, executed JUnit/XCTest summaries, logs, exact bridges and compiled thin host sources retained. DerivedData/xcresult build caches omitted. Pin/bootstrap records and exact production component sources are included. No commit or push performed.'}
(p/'SUMMARY.json').write_text(json.dumps(report,indent=2)+'\n')
md=f'''The independent Reading Notes forward test completed real iOS and Android rendering, scrolling, activation, and caller replacement. No component correction was needed after rendering. The final scoped result is **needs_review**, with no confirmed component failures: Android **18 passed / 0 failed / 6 unassessed**; iOS **12 passed / 0 failed / 12 unassessed**. Each platform has 24 required assertions from 30 matrix cells, including 6 explicitly justified N/A cells.

The original typed design was sealed before component code and acquisition: `{report['original_design_lock_sha256']}`. The measurement-scope amendment uses `{report['scoped_design_lock_sha256']}`. Its numeric source is byte-identical. It names `layout_box` explicitly; existing collectors export accessibility/semantic boxes, so width/gap remain unassessed on both platforms. iOS font/color also remain unassessed. Android native text layout matches 16sp and #FF204B6D in all three selected states. Both platforms establish the heading, status and distant footer in initial/opened/replaced states, one `notes.open` callback after demonstrated activation, and no callback after demonstrated same-session caller replacement. Open state survives replacement.

| Native run | Tests | Screenshots | Command wall time |
| --- | ---: | ---: | ---: |
'''
for r in rows:md+=f"| {r['run']} | {r['native_test_count']} | {r['screenshot_count']} | {r['command_wall_seconds']:.2f}s |\n"
md+='''
The independent design is an agent-authored reference fixed in a separate context, not a claim of human approval. It covers a calm long reading component with twelve complete rows, two visual markers, a disclosure action, and independently changing caller title/footer. SwiftUI production code is a local package and Compose production code sits in `app/src/main`; each thin bridge calls that real component. The two caller inputs preserve the same mounted component identity. I inspected five overlapping initial frames per platform plus the activation and replacement target frames; the full initial visual intent passes. See [iOS contact sheet](ios-contact.png), [Android contact sheet](android-contact.png), the SHA-bound manual reviews, and the raw screenshots under [evidence](evidence).

The original negative suite found one tool input-validation defect: a selector object containing an extra `expected` key was accepted. It never changed the generated expected value. Root fixed the validation; the exact fresh CLI retry now rejects, and all eleven focused source/route/binding/plan mutation probes reject. Both the original accepted output and corrected failures remain in the repository. The root neutral probe also clarified layout allocation versus accessibility bounds; I preserved the original contract, plan, tool snapshot, and checks, then replayed unchanged raw observations under a separate scoped lock. No numbers, tolerance, selectors, caller data, action paths or component implementation were changed in response to screenshots.

`ui_loop` initial-viewport capture/review passes on both platforms. These profiles stage an already collected frame after checking its original observation/input/source/image hashes and the successful real test execution. They explicitly report evidence reuse, not another native run. Complete-scroll visual review and typed native checks are recorded separately; a viewport pass does not replace their unassessed cells.

The workflow is usable with these pinned hosts, with clear raw evidence and state-bound callbacks, but requires substantial manual design translation and binding. iOS capture took 118 seconds because it repeated full-content sweeps around target navigation. The main diagnostic limitation is that unsupported layout-box assertions currently report a generic missing shared-frame reason. The final result is not complete style acceptance.

Scope limits: one 390-width light/LTR default-text scenario; iOS simulator App/XCUITest, Android Paparazzi attached ComposeView semantics/OnClick; no Android Activity/physical-touch, real business page, navigation, keyboard or lifecycle claim. There is no independent pixel golden, and visual interpretation remains fallible. Unsupported exact layout and iOS typography/color measurements stay unassessed.

Caller/setup mistakes and retries are preserved: an initially pre-created bootstrap directory was corrected to a fresh child; the original negative suite failed because it discovered the accepted binding key; and two scoped compiles first used a nonexistent copied CLI after a diagnostic command prevented the copy, then passed after an explicit tool snapshot copy. Native builds/tests had no failures. No native screenshot retry or production correction was necessary.

Exact tool versions are SHA-inventoried in `tools-used`, `tools-scoped`, and `tools-final`; acquisition manifests pin observer sources/templates. The pre-fix binding acceptance attempt did not save the old tool bytes, so that version is established by the preserved accepted CLI output rather than a local code snapshot. All 112 collected native PNGs, observations, test reports/logs and exact component/bridge/host sources are retained. Build caches and xcresult bundles are omitted from the portable archive. No commit or push was created.

`SUMMARY.json` supplies structured counts, timing, scope limits, failure history, and tool snapshot paths. `FREEZE.json` pins this summary and the full portable file inventory with a UTC timestamp.
'''
(p/'SUMMARY.md').write_text(md)
exclude={'SHA256SUMS.json','FREEZE.json'}
hashes={str(f.relative_to(p)):sha(f)for f in sorted(p.rglob('*'))if f.is_file()and str(f.relative_to(p))not in exclude}
(p/'SHA256SUMS.json').write_text(json.dumps(hashes,indent=2)+'\n')
freeze={'frozen_at_utc':report['frozen_at_utc'],'summary_md_sha256':sha(p/'SUMMARY.md'),'summary_json_sha256':sha(p/'SUMMARY.json'),'inventory_sha256':sha(p/'SHA256SUMS.json'),'file_count':len(hashes),'design_lock_sha256':report['original_design_lock_sha256'],'scoped_design_lock_sha256':report['scoped_design_lock_sha256'],'instruction':'Frozen independent report. Additional work must be an addendum; do not alter the recorded summary or evidence.'}
(p/'FREEZE.json').write_text(json.dumps(freeze,indent=2)+'\n');print(json.dumps(freeze,indent=2))
